import{_ as t,o as a,c as o,a5 as r}from"./chunks/framework.UjrY2eRK.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"operations/troubleshooting.md","filePath":"operations/troubleshooting.md","lastUpdated":1788169631000}'),i={name:"operations/troubleshooting.md"};function n(s,e,d,l,u,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="health-returns-503" tabindex="-1">Health returns 503 <a class="header-anchor" href="#health-returns-503" aria-label="Permalink to &quot;Health returns 503&quot;">​</a></h2><p>The runtime configuration, storage connection, or schema is unavailable. Check startup logs, required secrets, D1 bindings, SQLite volume permissions, and pending migrations. Health deliberately does not expose the internal failure.</p><h2 id="notification-requests-return-429" tabindex="-1">Notification requests return 429 <a class="header-anchor" href="#notification-requests-return-429" aria-label="Permalink to &quot;Notification requests return 429&quot;">​</a></h2><p>The short source rate limit or the persistent daily delivery budget was exhausted. Confirm the traffic source before raising a limit; do not bypass delivery coordination.</p><h2 id="notification-requests-return-502" tabindex="-1">Notification requests return 502 <a class="header-anchor" href="#notification-requests-return-502" aria-label="Permalink to &quot;Notification requests return 502&quot;">​</a></h2><p>Google OAuth or FCM failed or timed out. Verify outbound HTTPS connectivity, the Firebase service-account scope, project ID, and FCM API status. The response is retryable according to the Matrix push contract.</p><h2 id="notification-requests-return-503" tabindex="-1">Notification requests return 503 <a class="header-anchor" href="#notification-requests-return-503" aria-label="Permalink to &quot;Notification requests return 503&quot;">​</a></h2><p>Configuration, storage, schema validation, or concurrent delivery coordination was unavailable. Check runtime health and storage before retrying.</p><h2 id="self-hosted-source-limits-group-clients-together" tabindex="-1">Self-hosted source limits group clients together <a class="header-anchor" href="#self-hosted-source-limits-group-clients-together" aria-label="Permalink to &quot;Self-hosted source limits group clients together&quot;">​</a></h2><p>The gateway could not establish a trustworthy client address. Configure every direct proxy network in <code>TRINITY_PUSH_GATEWAY_TRUSTED_PROXY_CIDRS</code>, select the header your proxy replaces, and ensure untrusted clients cannot connect directly to the container port.</p><h2 id="sqlite-does-not-start" tabindex="-1">SQLite does not start <a class="header-anchor" href="#sqlite-does-not-start" aria-label="Permalink to &quot;SQLite does not start&quot;">​</a></h2><p>Keep the database, <code>-wal</code>, and <code>-shm</code> files together on local storage. Check UID/GID 1000 ownership, free disk space, integrity, and migration compatibility. Network filesystems and horizontal replicas are unsupported.</p><h2 id="admin-returns-404" tabindex="-1"><code>/admin/*</code> returns 404 <a class="header-anchor" href="#admin-returns-404" aria-label="Permalink to &quot;`/admin/*` returns 404&quot;">​</a></h2><p>Administration is disabled. Apply both Compose files and both environment files, or deliberately leave it disabled. Other administration variables and secrets are ignored in disabled mode.</p><h2 id="admin-returns-503-but-health-is-ready" tabindex="-1"><code>/admin/*</code> returns 503 but <code>/health</code> is ready <a class="header-anchor" href="#admin-returns-503-but-health-is-ready" aria-label="Permalink to &quot;`/admin/*` returns 503 but `/health` is ready&quot;">​</a></h2><p>Delivery is correctly isolated from an invalid or failed administration subsystem. Check exact public origin and issuer values, both secret files, <code>admin.sqlite</code> ownership/separation, administration migrations, browser assets, and available disk space. Never point administration at <code>gateway.sqlite</code>.</p><h2 id="login-returns-unavailable" tabindex="-1">Login returns unavailable <a class="header-anchor" href="#login-returns-unavailable" aria-label="Permalink to &quot;Login returns unavailable&quot;">​</a></h2><p>Fetch the configured issuer&#39;s discovery document from the gateway host. Verify its exact issuer, authorization/token/JWKS endpoints, client authentication method, client secret, PKCE support, and callback URL. Check provider and gateway clock synchronization. Provider tokens and raw claims are intentionally not logged.</p><h2 id="login-returns-forbidden" tabindex="-1">Login returns forbidden <a class="header-anchor" href="#login-returns-forbidden" aria-label="Permalink to &quot;Login returns forbidden&quot;">​</a></h2><p>Authentication succeeded but the configured group claim was missing or did not contain the exact required group. Pocket ID requires the <code>groups</code> scope and an allowed group assignment. Authentik requires the profile mapping and groups in the ID token. Test a known member and non-member.</p><h2 id="the-ui-loads-but-a-deep-link-or-asset-fails" tabindex="-1">The UI loads but a deep link or asset fails <a class="header-anchor" href="#the-ui-loads-but-a-deep-link-or-asset-fails" aria-label="Permalink to &quot;The UI loads but a deep link or asset fails&quot;">​</a></h2><p>Proxy every <code>/admin/*</code> request to the gateway without rewriting its path. Do not configure a proxy-level SPA fallback: the gateway serves only its fixed deep links and returns 404 for unknown routes. Hashed JS/CSS assets are immutable; HTML is no-store. Purge any proxy rule that caches HTML as an asset.</p><h2 id="an-operator-action-is-busy-or-unknown" tabindex="-1">An Operator Action is busy or unknown <a class="header-anchor" href="#an-operator-action-is-busy-or-unknown" aria-label="Permalink to &quot;An Operator Action is busy or unknown&quot;">​</a></h2><p>Respect the returned lease/cooldown. Do not retry <code>outcome_unknown</code> automatically because execution may have completed before audit finalization. Review audit outcomes, <code>/data/backups</code>, health, and redacted logs first.</p>',25)])])}const b=t(i,[["render",n]]);export{p as __pageData,b as default};
